// Implement runs a managed feature as a graph. The factory decides which path a
// run takes: the parent issue takes the coordinator path, and each story
// sub-issue takes the worker path with a session, branch and worktree of its
// own. Independent stories therefore build side by side, and a story that fails
// does not stop the others.
//
// Coordinator (parent issue). It first brings the repository's base branch
// (main) into the feature branch, so stories build on a current base. An owner
// reply that resumes parked stories enters at this base sync again, so a fix
// that reached main while the stories waited reaches them too. Then it
// merges finished stories until none is left and starts every story that is
// ready. While stories build it rests at await
// and ends the run; it wakes when a story changes state. When no story can start
// or finish, it writes the hand-off report. If any story is parked, it asks the
// owner one question that lists them all and waits. If every story is merged,
// it brings main in once more and reports completion on the parent once. When
// main conflicts with the feature branch, a resolver agent merges it in the
// parent's worktree and resolves the conflict; the factory saves a completed
// answer and syncs again. Only a blocked resolver asks the owner. The
// coordinator itself never writes code.
//
// Worker (story sub-issue). The repair budget is counted in the story ledger:
// the first attempt and two repairs. Each permitted entry first synchronizes
// the selected story base; conflicts or exhausted sync retries park the story.
// One write-access agent writes the code and
// its tailored unit tests and runs them. Only an accepted completed answer is
// saved (committed and pushed), and only then is the story done. A blocked
// answer parks the story at once with the agent's own reason. An incomplete
// answer, a failed attempt or a failed save counts one attempt and goes back to
// the budget decision; the next attempt receives the reason. An exhausted budget
// parks the story with the last worker's own reason.
//
// This file is the only place the flow lives. Go supplies steps and never picks
// the next step. Every node has a positive lf_limit; the limits on the coordinator
// loop are sized for the largest story set plus owner resumes, and the worker
// limits hold the three attempts plus the final park.
digraph implement {
 graph [team="dotnet-web", mode="implement", profile_version="1", start="select_path"];

 // ---- Path selection ---------------------------------------------------------
 select_path [lf_action="lf_implement_select", lf_outcomes="coordinator,worker", lf_limit="4"];

 // ---- Coordinator --------------------------------------------------------------
 merge      [lf_action="lf_implement_merge", lf_outcomes="merged,parked,none,retry", lf_limit="64"];
 ready      [lf_action="lf_implement_ready", lf_outcomes="started,waiting,drained", lf_limit="64"];
 await      [lf_action="lf_implement_await", lf_outcomes="go", lf_limit="64"];
 handoff    [lf_action="lf_implement_handoff", lf_outcomes="posted", lf_limit="16"];
 any_parked [lf_action="lf_implement_any_parked", lf_outcomes="true,false", lf_limit="16"];
 ask_owner  [lf_action="lf_implement_ask", lf_outcomes="published", lf_source="sync_start", lf_limit="16"];
 report_done [lf_action="lf_implement_report_done", lf_outcomes="published", lf_source="merge", lf_limit="16"];

 // ---- Base sync ------------------------------------------------------------------
 sync_start          [lf_action="lf_sync_base", lf_outcomes="synced,current,conflict,retry", lf_limit="32"];
 sync_start_resolve  [lf_action="lf_agent", lf_outcomes="success,failed", lf_agent_markdown="sync-resolver", lf_skills="implement-result,dotnet-web-engineering", lf_limit="3"];
 sync_start_resolved [lf_action="lf_implement_resolved", lf_outcomes="resolved,blocked,retry", lf_source="sync_start_resolve", lf_limit="3"];
 sync_done           [lf_action="lf_sync_base", lf_outcomes="synced,current,conflict,retry", lf_limit="8"];
 sync_done_resolve   [lf_action="lf_agent", lf_outcomes="success,failed", lf_agent_markdown="sync-resolver", lf_skills="implement-result,dotnet-web-engineering", lf_limit="3"];
 sync_done_resolved  [lf_action="lf_implement_resolved", lf_outcomes="resolved,blocked,retry", lf_source="sync_done_resolve", lf_limit="3"];

 // ---- Worker -----------------------------------------------------------------------
 sync_before_worker [lf_action="lf_sync_base", lf_outcomes="synced,current,conflict,retry", lf_limit="8"];
 budget        [lf_action="lf_implement_budget", lf_outcomes="run,park", lf_limit="8"];
 worker_agent  [lf_action="lf_agent", lf_outcomes="success,failed", lf_agent_markdown="story-worker", lf_skills="implement-result,dotnet-web-engineering", lf_limit="3"];
 worker_result [lf_action="lf_implement_result", lf_outcomes="completed,incomplete,blocked", lf_source="worker_agent", lf_limit="3"];
 story_done    [lf_action="lf_implement_story_done", lf_outcomes="done,retry", lf_limit="3"];
 park_story    [lf_action="lf_implement_park", lf_outcomes="parked", lf_limit="4"];

 // ---- Terminals ------------------------------------------------------------------------
 waiting       [lf_terminal="true"];
 finished      [lf_terminal="true"];
 worker_done   [lf_terminal="true"];
 worker_parked [lf_terminal="true"];

 select_path -> sync_start [lf_on="coordinator"];
 select_path -> budget     [lf_on="worker"];

 // Coordinator start: bring main into the feature branch before any story
 // starts. A conflict goes to the resolver; a completed resolution is saved and
 // the sync runs again. A busy or moved branch rests at await and goes on.
 sync_start          -> merge               [lf_on="synced"];
 sync_start          -> merge               [lf_on="current"];
 sync_start          -> sync_start_resolve  [lf_on="conflict"];
 sync_start          -> await               [lf_on="retry"];
 sync_start_resolve  -> sync_start_resolved [lf_on="success"];
 sync_start_resolve  -> sync_start          [lf_on="failed"];
 sync_start_resolved -> sync_start          [lf_on="resolved"];
 sync_start_resolved -> sync_start          [lf_on="retry"];
 sync_start_resolved -> waiting             [lf_on="blocked"];

 // Coordinator: merge until none, then ready. A started or waiting result rests
 // at await; a drained one is the end of the work.
 merge -> merge   [lf_on="merged"];
 merge -> merge   [lf_on="parked"];
 merge -> ready   [lf_on="none"];
 merge -> await   [lf_on="retry"];
 ready -> await   [lf_on="started"];
 ready -> await   [lf_on="waiting"];
 ready -> handoff [lf_on="drained"];
 await -> merge   [lf_on="go"];

 // After the hand-off, one question for every parked story, or main once more
 // and the completion reply and finish.
 handoff     -> any_parked  [lf_on="posted"];
 any_parked  -> ask_owner   [lf_on="true"];
 any_parked  -> sync_done   [lf_on="false"];
 ask_owner   -> waiting     [lf_on="published"];
 report_done -> finished    [lf_on="published"];

 // Coordinator end: bring main in again before the completion reply.
 sync_done          -> report_done        [lf_on="synced"];
 sync_done          -> report_done        [lf_on="current"];
 sync_done          -> sync_done_resolve  [lf_on="conflict"];
 sync_done          -> sync_done          [lf_on="retry"];
 sync_done_resolve  -> sync_done_resolved [lf_on="success"];
 sync_done_resolve  -> sync_done          [lf_on="failed"];
 sync_done_resolved -> sync_done          [lf_on="resolved"];
 sync_done_resolved -> sync_done          [lf_on="retry"];
 sync_done_resolved -> waiting            [lf_on="blocked"];

 // Worker: budget, then synchronize the selected story base before the agent. Completed is saved; blocked parks at once. An
 // incomplete answer, a failed attempt or a failed save goes back to the budget.
 budget        -> sync_before_worker [lf_on="run"];
 sync_before_worker -> worker_agent [lf_on="synced"];
 sync_before_worker -> worker_agent [lf_on="current"];
 sync_before_worker -> sync_before_worker [lf_on="retry"];
 sync_before_worker -> park_story [lf_on="conflict"];
 budget        -> park_story    [lf_on="park"];
 worker_agent  -> worker_result [lf_on="success"];
 worker_agent  -> budget        [lf_on="failed"];
 worker_result -> story_done    [lf_on="completed"];
 worker_result -> budget        [lf_on="incomplete"];
 worker_result -> park_story    [lf_on="blocked"];
 story_done    -> worker_done   [lf_on="done"];
 story_done    -> budget        [lf_on="retry"];
 park_story    -> worker_parked [lf_on="parked"];
}

# completed

The story is built and its unit tests pass. No questions and no reason.

When you decided a gap the plan did not foresee, list each decision in
`deviations` as one short line: what you chose, why, and file:line. Leave the
list out when there is none, and never mark a deviation in the code.

```json
{
  "result": {
    "outcome": "completed",
    "comment": "Summarise what was built and which tests you ran, in a sentence or two, and name each deviation in plain words; do not submit this example unchanged.",
    "payload": {
      "implement": {
        "stories": [],
        "deviations": [
          "Chose best-effort delivery with a retry key, because the provider removes duplicates only for a few minutes (path/to/file:42)."
        ]
      }
    }
  }
}
```

# incomplete

Part of the story is not done, and your time is about to run out or something
outside the story stops the work for now. Unfinished tasks alone are not a reason
to stop. Say what is left in plain language. The factory runs another attempt
with your reason, and parks the story and asks the owner only once the attempts
are spent.

```json
{
  "result": {
    "outcome": "incomplete",
    "comment": "Say what is built and what is not.",
    "reason": "Say plainly what is left to do and what stopped the work.",
    "payload": {
      "implement": {
        "stories": []
      }
    }
  }
}
```

# blocked

Every option would contradict an approved decision or a frozen acceptance
criterion, or the work needs access or credentials you cannot get. A gap you can
decide within the story's intent is a deviation on a completed result, not a
blocker. Say what blocks you. The story is parked at once and the owner is asked.

```json
{
  "result": {
    "outcome": "blocked",
    "comment": "Say what is built before the blocker.",
    "reason": "Say plainly which approved decision or criterion every option would break, or which access you lack.",
    "payload": {
      "implement": {
        "stories": []
      }
    }
  }
}
```

// Plan shapes a scope into stories in four owner-authorized stages, each with
// one reasoning role: set, story, technical and acceptance.
//
// The factory, not an agent, decides which stage a run is in. It answers the
// select_* decisions from retained authenticated state, so a run enters exactly
// one stage. Parent discussion selects set; automatic work with stories skips set.
//
// Every stage can answer discussion through an explicit comment and stop without
// changing drafts or approvals. Otherwise its agent drafts, asks the owner when it
// needs an answer, and otherwise applies its draft to the story and asks for
// review. A stage advances only through its gate, which reads "approved" from
// an owner reply; review-ready is never approval. Every wait is durable, and
// running out of passes stops the run in a resumable state.
//
// The set stage proposes the story set on the parent and waits for the owner to
// promote it. After promotion the story stage is a bounded creation cycle:
// story_pick selects the next promoted story without a draft, story_agent
// drafts it, and its review is published before the next pick. A pick that
// finds none parks the run at the owner waits. The cycle nodes carry
// lf_limit="13": twelve stories in a set plus one owner-requested revision.
digraph plan {
 graph [team="dotnet-web", mode="plan", profile_version="1", start="select_set"];

 // ---- Stage selection ------------------------------------------------------
 select_set        [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="set", lf_limit="24"];
 select_story      [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="story", lf_limit="24"];
 select_technical  [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="technical", lf_limit="24"];
 select_acceptance [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="acceptance", lf_limit="24"];

 // ---- Stage 1: story set ---------------------------------------------------
 set_loop     [lf_action="lf_loop", lf_outcomes="true,false", lf_field="response", lf_condition="set", lf_limit="8"];
 set_agent    [lf_action="lf_agent", lf_outcomes="success,failed", lf_agent_markdown="plan-set", lf_skills="plan-story-set", lf_limit="8"];
 set_question [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="ask", lf_source="set_agent", lf_limit="8"];
 set_draft    [lf_action="lf_plan_story", lf_source="set_agent", lf_outcomes="applied,conflict,failed,uncertain", lf_limit="8"];
 set_gate     [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="approved", lf_limit="8"];
 set_ask      [lf_action="lf_ask", lf_outcomes="published", lf_kind="question", lf_source="set_agent", lf_limit="8"];
 set_review   [lf_action="lf_ask", lf_outcomes="published", lf_kind="review", lf_source="set_agent", lf_limit="8"];

 // ---- Stage 2: stories (bounded creation cycle) ----------------------------
 story_loop     [lf_action="lf_loop", lf_outcomes="true,false", lf_field="response", lf_condition="story", lf_limit="8"];
 story_pick     [lf_action="lf_loop", lf_outcomes="true,false", lf_field="response", lf_condition="create", lf_limit="13"];
 story_agent    [lf_action="lf_agent", lf_outcomes="success,failed", lf_agent_markdown="plan-story", lf_skills="plan-story-shaping", lf_limit="13"];
 story_question [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="ask", lf_source="story_agent", lf_limit="13"];
 story_draft    [lf_action="lf_plan_story", lf_source="story_agent", lf_outcomes="applied,conflict,failed,uncertain", lf_limit="13"];
 story_gate     [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="approved", lf_limit="13"];
 story_ask      [lf_action="lf_ask", lf_outcomes="published", lf_kind="question", lf_source="story_agent", lf_limit="8"];
 story_review   [lf_action="lf_ask", lf_outcomes="published", lf_kind="review", lf_source="story_agent", lf_limit="13"];

 // ---- Stage 3: technical ---------------------------------------------------
 technical_loop     [lf_action="lf_loop", lf_outcomes="true,false", lf_field="response", lf_condition="technical", lf_limit="8"];
 technical_agent    [lf_action="lf_agent", lf_outcomes="success,failed", lf_agent_markdown="plan-technical", lf_skills="plan-technical-shaping", lf_limit="8"];
 technical_question [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="ask", lf_source="technical_agent", lf_limit="8"];
 technical_draft    [lf_action="lf_plan_story", lf_source="technical_agent", lf_outcomes="applied,conflict,failed,uncertain", lf_limit="8"];
 technical_gate     [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="approved", lf_limit="8"];
 technical_ask      [lf_action="lf_ask", lf_outcomes="published", lf_kind="question", lf_source="technical_agent", lf_limit="8"];
 technical_review   [lf_action="lf_ask", lf_outcomes="published", lf_kind="review", lf_source="technical_agent", lf_limit="8"];

 // ---- Stage 4: acceptance --------------------------------------------------
 acceptance_loop     [lf_action="lf_loop", lf_outcomes="true,false", lf_field="response", lf_condition="acceptance", lf_limit="8"];
 acceptance_agent    [lf_action="lf_agent", lf_outcomes="success,failed", lf_agent_markdown="plan-acceptance", lf_skills="plan-acceptance-shaping", lf_limit="8"];
 acceptance_question [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="ask", lf_source="acceptance_agent", lf_limit="8"];
 acceptance_draft    [lf_action="lf_plan_story", lf_source="acceptance_agent", lf_outcomes="applied,conflict,failed,uncertain", lf_limit="8"];
 acceptance_gate     [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="approved", lf_limit="8"];
 acceptance_ask      [lf_action="lf_ask", lf_outcomes="published", lf_kind="question", lf_source="acceptance_agent", lf_limit="8"];
 acceptance_review   [lf_action="lf_ask", lf_outcomes="published", lf_kind="review", lf_source="acceptance_agent", lf_limit="8"];

 set_answer [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="answer", lf_source="set_agent", lf_limit="13"];
 set_reply [lf_action="lf_comment", lf_outcomes="published", lf_kind="final", lf_source="set_agent", lf_limit="13"];
 set_answer -> set_reply [lf_on="true"];
 set_answer -> set_draft [lf_on="false"];
 set_reply -> waiting [lf_on="published"];

 story_answer [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="answer", lf_source="story_agent", lf_limit="13"];
 story_reply [lf_action="lf_comment", lf_outcomes="published", lf_kind="final", lf_source="story_agent", lf_limit="13"];
 story_answer -> story_reply [lf_on="true"];
 story_answer -> story_draft [lf_on="false"];
 story_reply -> waiting [lf_on="published"];

 technical_answer [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="answer", lf_source="technical_agent", lf_limit="13"];
 technical_reply [lf_action="lf_comment", lf_outcomes="published", lf_kind="final", lf_source="technical_agent", lf_limit="13"];
 technical_answer -> technical_reply [lf_on="true"];
 technical_answer -> technical_draft [lf_on="false"];
 technical_reply -> waiting [lf_on="published"];

 acceptance_answer [lf_action="lf_if", lf_outcomes="true,false", lf_field="response", lf_condition="answer", lf_source="acceptance_agent", lf_limit="13"];
 acceptance_reply [lf_action="lf_comment", lf_outcomes="published", lf_kind="final", lf_source="acceptance_agent", lf_limit="13"];
 acceptance_answer -> acceptance_reply [lf_on="true"];
 acceptance_answer -> acceptance_draft [lf_on="false"];
 acceptance_reply -> waiting [lf_on="published"];

 // ---- Failure and terminals ------------------------------------------------
 failed   [lf_action="lf_comment", lf_outcomes="published", lf_kind="failure", lf_limit="1"];
 waiting  [lf_terminal="true"];
 promoted [lf_terminal="true"];
 stopped  [lf_terminal="true"];

 // Stage selection: the first true decision picks the stage; none stops.
 select_set        -> set_loop          [lf_on="true"];
 select_set        -> select_story      [lf_on="false"];   // stories exist; skip the set
 select_story      -> story_loop        [lf_on="true"];
 select_story      -> select_technical  [lf_on="false"];
 select_technical  -> technical_loop    [lf_on="true"];
 select_technical  -> select_acceptance [lf_on="false"];
 select_acceptance -> acceptance_loop   [lf_on="true"];
 select_acceptance -> stopped           [lf_on="false"];

 // Stage 1: propose the story set and wait for the owner to promote it.
 set_loop     -> set_agent    [lf_on="true"];
 set_loop     -> stopped      [lf_on="false"];      // out of passes
 set_agent    -> set_question [lf_on="success"];
 set_question -> set_ask      [lf_on="true"];       // needs an answer
 set_question -> set_answer    [lf_on="false"];      // has a set; apply it
 set_draft    -> set_gate     [lf_on="applied"];
 set_gate     -> promoted     [lf_on="true"];       // the owner approved
 set_gate     -> set_review   [lf_on="false"];      // asks if the set stands
 set_ask      -> waiting      [lf_on="published"];
 set_review   -> waiting      [lf_on="published"];

 // Stage 2: draft one story per pick; each review is published before the next.
 story_loop     -> story_agent    [lf_on="true"];
 story_loop     -> stopped        [lf_on="false"];    // out of passes
 story_agent    -> story_question [lf_on="success"];
 story_question -> story_ask      [lf_on="true"];     // needs an answer
 story_question -> story_answer    [lf_on="false"];    // has a draft; apply it
 story_draft    -> story_gate     [lf_on="applied"];
 story_gate     -> promoted       [lf_on="true"];     // the owner approved
 story_gate     -> story_review   [lf_on="false"];    // asks if the draft stands
 story_ask      -> waiting        [lf_on="published"];
 story_review   -> story_pick     [lf_on="published"];
 story_pick     -> story_agent    [lf_on="true"];     // another story has no draft
 story_pick     -> waiting        [lf_on="false"];    // all drafted; owner reviews

 // Stage 3: technical shaping, same shape as the set stage.
 technical_loop     -> technical_agent    [lf_on="true"];
 technical_loop     -> stopped            [lf_on="false"];    // out of passes
 technical_agent    -> technical_question [lf_on="success"];
 technical_question -> technical_ask      [lf_on="true"];     // needs an answer
 technical_question -> technical_answer    [lf_on="false"];    // has a draft; apply it
 technical_draft    -> technical_gate     [lf_on="applied"];
 technical_gate     -> promoted           [lf_on="true"];     // the owner approved
 technical_gate     -> technical_review   [lf_on="false"];    // asks if the draft stands
 technical_ask      -> waiting            [lf_on="published"];
